import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"熊族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/熊族.md","filePath":"表层/种族/熊族.md","lastUpdated":1787065118000}'),i={name:"表层/种族/熊族.md"};function e(n,a,s,h,u,g){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="熊族" tabindex="-1">熊族 <a class="header-anchor" href="#熊族" aria-label="Permalink to &quot;熊族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>熊族是五大主族之一，共同体时期承担工业相关的一切，以<strong>建设与发展欲</strong>为种族核心特质。共同体末期，熊族在内斗中被鹿族排挤，此后举族北迁至北境恶劣地带，生活质量长期低下，收复故土成为族群执念。当代熊族为<strong>世界一极</strong>，拥有全大陆最先进的工业水平，数百年来保持着红色的旗帜与五星的一角作为标志，无比怀念共同体时期，渴望南下光复故土。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有熊类动物的典型福瑞形态。</li><li><strong>体格</strong>：体型魁梧壮硕，在同为兽族的主族中体格最为强健。</li><li><strong>力量</strong>：在纯粹的身体力量上具有显著优势，适合重体力劳动与工业活动。</li><li><strong>毛色</strong>：以棕色、黑色为主。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-建设与发展欲" tabindex="-1">核心特质：建设与发展欲 <a class="header-anchor" href="#核心特质-建设与发展欲" aria-label="Permalink to &quot;核心特质：建设与发展欲&quot;">​</a></h3><ul><li><strong>建造驱动</strong>：天生对建造与工程有强烈的内在驱动，将劳动与建设视为种族的天职。</li><li><strong>集体协作</strong>：喜欢集体协作进行大型项目，极少出现内部分裂。</li><li><strong>发展渴望</strong>：对发展与进步怀有强烈的渴望，不满足于维持现状。</li><li><strong>韧性</strong>：具备在极端环境中坚持发展的韧性——即使身处北境苦寒之地，仍能维持全大陆最先进的工业水平。</li></ul><h3 id="性格特征" tabindex="-1">性格特征 <a class="header-anchor" href="#性格特征" aria-label="Permalink to &quot;性格特征&quot;">​</a></h3><ul><li><strong>团结</strong>：极高的民众凝聚力与战斗意志。</li><li><strong>务实</strong>：善于将技术转化为实际生产力，注重实际成果。</li><li><strong>坚韧</strong>：在北境极寒环境中挣扎求生数百年，培养了极强的种族韧性。</li><li><strong>怀旧</strong>：对共同体时期的美好时光有着深刻的怀念。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体时期-工业担当" tabindex="-1">共同体时期：工业担当 <a class="header-anchor" href="#共同体时期-工业担当" aria-label="Permalink to &quot;共同体时期：工业担当&quot;">​</a></h3><p>在五大主族分工的共同体体系中，熊族承担<strong>工业相关的一切</strong>：</p><ul><li>负责共同体的基础设施建设。</li><li>主导各类机械与装备的生产制造。</li><li>将鹿族的科研成果转化为实际工业产品。</li><li>在共同体五星旗帜上，熊族占据一角。</li></ul><h3 id="北迁史" tabindex="-1">北迁史 <a class="header-anchor" href="#北迁史" aria-label="Permalink to &quot;北迁史&quot;">​</a></h3><p>共同体末期，鹿族主导&quot;神明复活计划&quot;夺走实权，事实上排挤了鹤族；熊族不服被鹿族排挤，牛族没有主见、甲族近乎死光，熊族孤立无援，高层对共同体失去信心，遂将族人向北方工业地区（熊族实控区域）集中。随共同体解体、事态恶化、新五族咄咄逼人，不愿起冲突的熊族或被动或主动愈发北迁，最终迁至<strong>北境恶劣地带</strong>，生活质量长期低下。</p><p>熊族宣称的故土在黑暗时代因军阀贵族割据、族群瓜分，被鹿族等族群占据。<strong>收复共同体时期的核心故土</strong>从此成为族群执念。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><h3 id="熊国-世界另一极" tabindex="-1">熊国：世界另一极 <a class="header-anchor" href="#熊国-世界另一极" aria-label="Permalink to &quot;熊国：世界另一极&quot;">​</a></h3><p>熊族在黑暗时代后建立独立国家——<strong>熊国</strong>，是当前世界的另一极：</p><ul><li><strong>工业基础</strong>：即使在极北严酷环境中，仍保持全大陆最先进的工业水平，并发展出独特的寒冷地带工业体系。</li><li><strong>常规军队</strong>：拥有体量庞大到令人窒息的常规军队（&quot;钢铁洪流&quot;），陆军实力对鹿族形成压倒性优势。</li><li><strong>国家体制</strong>：高度集中化、集权化，决策高效，动员能力强。</li><li><strong>民众凝聚力</strong>：极高的民众凝聚力与战斗意志，不易因斩首行动或高层损失而溃败。</li></ul><h4 id="劣势" tabindex="-1">劣势 <a class="header-anchor" href="#劣势" aria-label="Permalink to &quot;劣势&quot;">​</a></h4><ul><li><strong>法师力量</strong>：几乎没有成体系的法师力量，在超自然战力维度上与鹿族存在显著差距。</li><li><strong>粮食供应</strong>：极北之地的恶劣环境长期限制农业发展，粮食供应长期紧张。</li><li><strong>科技短板</strong>：科技水平相对鹿国落后，尤其在电子与生物技术领域。</li></ul><h3 id="修正主义" tabindex="-1">修正主义 <a class="header-anchor" href="#修正主义" aria-label="Permalink to &quot;修正主义&quot;">​</a></h3><p>熊国的集权体制已出现<strong>修正主义</strong>倾向，与共同体时期的原始红色理想有所偏离。其成因并非单纯的&quot;忘本&quot;，而是<strong>生存环境压迫 + 行政短板 + 仇恨发酵</strong>的结果：</p><ul><li>北境恶劣的生存环境让&quot;收复故土&quot;成为族群存续的唯一途径；</li><li>熊族本就不擅长行政的短板导致内部治理问题频发；</li><li>高层为转移矛盾，刻意放大对鹿族的仇恨，最终让熊族的&quot;团结&quot;走向黑暗面，形成极端集权、军国主义的修正主义倾向。</li></ul><h3 id="旗帜与怀念" tabindex="-1">旗帜与怀念 <a class="header-anchor" href="#旗帜与怀念" aria-label="Permalink to &quot;旗帜与怀念&quot;">​</a></h3><p>熊族是共同体遗产最忠实的继承者。数百年间，他们始终认为自己是共同体的一员，<strong>保持着红色的旗帜</strong>与<strong>五星的一角</strong>作为种族标志，无比怀念过去神明还在时共同体的日子，渴望南下反攻，夺回家园，光复共同体。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./鹿族">鹿族</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li></ul><hr>',36)])])}const q=r(i,[["render",e]]);export{c as __pageData,q as default};
